import{_ as t,o as n,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-6-otp-verification/report3_spec.md","filePath":"feature/authentication/3-2-6-otp-verification/report3_spec.md"}'),s={name:"feature/authentication/3-2-6-otp-verification/report3_spec.md"};function r(a,e,l,p,d,u){return n(),o("div",null,[...e[0]||(e[0]=[i("<p><strong>3.2.6 OTP Verification (Phone Linking)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens &quot;Link phone&quot; on their profile, enters a phone number, and then enters the six-digit code they receive.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: A signed-in user (Bearer token required) linking a phone number to their account.</li><li><strong>Purpose</strong>: Confirm ownership of a phone number with a short-lived one-time code before attaching it to the account.</li><li><strong>Interface</strong>: A &quot;Link phone&quot; modal on the Profile page, with two steps: a phone number input, then a six-digit code input.</li><li><strong>Data Processing</strong>: Normalizes the phone number, generates a 6-digit numeric code, stores the code with the phone in Redis with a 10-minute TTL, enforces a 60-second resend cooldown and a 5-attempt wrong-code limit, and on success sets user.phone. The code is delivered by email to the account&#39;s own address, not by SMS.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Link Phone modal (Profile page):</p><ul><li>Step &quot;phone&quot;: a phone number input plus Cancel / &quot;Send OTP&quot; buttons; disabled while empty or sending.</li><li>Step &quot;otp&quot;: a hint line plus a six-digit code input, plus Cancel / &quot;Verify&quot; buttons; disabled while empty or verifying.</li><li>On send success: toast, advances to the &quot;otp&quot; step.</li><li>On verify success: toast, closes and resets the modal.</li><li>On any error: toast built from the error response.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: phone (link step); otpCode (verify step). Both endpoints require a valid Authorization Bearer header.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: userId (from the access token), pending code + phone stored in Redis (TTL 10 min), a resend-cooldown marker (TTL 60s), a wrong-attempt counter (TTL 10 min), user.phone.</li><li><strong>Output</strong>: no payload, 200, on both endpoints.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-03</strong>: Numeric OTP is 6 digits, TTL 10 minutes, single-use, cleared on success.</li><li><strong>BR-04</strong>: Resend has a 60-second cooldown, scoped per userId.</li><li><strong>BR-07</strong>: Phone must normalize to a valid E.164 number, else 400 INVALID_PHONE. Phone already used by a different user -&gt; 409 PHONE_ALREADY_IN_USE. A repeat link call inside the cooldown -&gt; 429 RATE_LIMIT_EXCEEDED, the pending code is not replaced. Wrong code increments the attempt counter; on the 5th wrong attempt both the code and the counter are deleted and the answer is 400 OTP_TOO_MANY_ATTEMPTS; below 5, 400 OTP_INVALID. Correct code deletes both keys, re-checks phone uniqueness (race guard), and sets user.phone.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>phone empty or invalid format -&gt; Display: <strong>MSG02</strong></li><li>otpCode empty -&gt; Display: <strong>MSG02</strong></li><li>otpCode invalid or expired -&gt; Display: <strong>MSG20</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The signed-in user opens the &quot;Link phone&quot; modal and enters a phone number.</li><li>The client calls the link-phone endpoint with the Bearer token.</li><li>The system normalizes the phone number, checks it is not already used by another user, generates a 6-digit code, stores it with the phone in Redis (TTL 10 min), starts the 60s cooldown, and emails the code.</li><li>The user enters the code in the modal&#39;s second step.</li><li>The client calls the verify endpoint with the Bearer token.</li><li>The system matches the code, clears the pending code and attempt counter, re-checks phone uniqueness, and sets user.phone.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: phone fails normalization -&gt; 400 INVALID_PHONE, Display: <strong>MSG02</strong>. 2.a2: The user corrects the phone number and resubmits.</li><li>2.b1: Phone already used by another user -&gt; 409 PHONE_ALREADY_IN_USE. 2.b2: The user enters a different phone number.</li><li>2.c1: link-phone called again inside the 60s cooldown -&gt; 429 RATE_LIMIT_EXCEEDED. 2.c2: The user waits for the cooldown to elapse.</li><li>5.a1: No pending code (never requested or expired) -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 5.a2: The user requests a new code.</li><li>5.b1: Wrong code, below 5 attempts -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 5.b2: The user re-enters the code.</li><li>5.c1: 5th wrong attempt -&gt; 400 OTP_TOO_MANY_ATTEMPTS; the pending code is discarded. 5.c2: The user must restart from step 1 for a new code.</li><li>5.d1: Correct code, but the phone was taken by another user meanwhile -&gt; 409 PHONE_ALREADY_IN_USE. 5.d2: The user enters a different phone number and restarts.</li><li>Missing/expired Bearer token on either call -&gt; 401 INVALID_CREDENTIALS; user is redirected to sign in.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>On success: user.phone is set to the normalized number; the pending code and attempt counter are cleared.</li><li>On failure: no change to user.phone; Redis state reflects the specific failure path.</li></ul>",14)])])}const g=t(s,[["render",r]]);export{h as __pageData,g as default};
